import SwiftUI
import NurayaCore
struct QuranModesView:View {
    @ObservedObject var state:AppState;@State private var query=""
    var body:some View {PageContainer(dark:state.settings.dark){AssetImage(content:state.content,path:"brand/quran_\(state.settings.dark ? "dark":"light").jpg",fit:true).frame(height:155).clipShape(RoundedRectangle(cornerRadius:22));Text("Pilih cara membaca").font(.system(size:26,weight:.semibold));NavigationLink(value:Route.search){MenuRow(title:"Cari ayat · makna & suara",icon:"search",dark:state.settings.dark)};TextField("Cari cara membaca",text:$query).textFieldStyle(.roundedBorder);ForEach(state.content.modes.filter {query.isEmpty || Normalization.search($0.titleId).contains(Normalization.search(query))}){mode in NavigationLink {if mode.id=="thematic" {ThemesView(state:state)}else {SurahList(state:state,mode:mode.id)}}label:{HStack(spacing:16){AssetImage(content:state.content,path:"brand/covers/\(mode.id=="madinah_tajwid" ? "madinah":mode.id).png",fit:true).frame(width:84,height:120);VStack(alignment:.leading,spacing:8){Text(state.translated(mode.titleId,mode.titleEn)).font(.system(size:22,weight:.semibold));Text(state.translated(mode.descriptionId,mode.descriptionEn)).font(.system(size:16)).foregroundStyle(.secondary);Text("Buka bacaan").font(.system(size:16,weight:.semibold))}}.padding(18).frame(maxWidth:.infinity,alignment:.leading).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:20))}}}}
}
struct SurahList:View {
    @ObservedObject var state:AppState;let mode:String;@State private var query="",juz=false
    var body:some View {PageContainer(dark:state.settings.dark){TextField("Cari surah atau nomor",text:$query).textFieldStyle(.roundedBorder);Picker("Daftar",selection:$juz){Text("Surah").tag(false);Text("Juz").tag(true)}.pickerStyle(.segmented)
        if juz {ForEach(1...30,id:\.self){j in if let v=state.content.corpus.verses.first(where:{$0.juz==j}) {Button{state.open(v.reference,mode:mode)}label:{MenuRow(title:"Juz \(j)",subtitle:state.content.corpus.surahs[v.surah-1].name+" · Ayat \(v.ayah)",icon:"book-open-cover",dark:state.settings.dark)}}}}
        else {ForEach(state.content.corpus.surahs.filter {query.isEmpty || String($0.id)==query || Normalization.search($0.name).contains(Normalization.search(query))}){s in Button{state.open(Reference(s.id,1),mode:mode)}label:{HStack(spacing:14){Text(String(s.id)).font(.system(size:18,weight:.semibold)).frame(width:44,height:44).background(Palette(dark:state.settings.dark).raised,in:RoundedRectangle(cornerRadius:14));VStack(alignment:.leading,spacing:6){Text(s.name).font(.system(size:20,weight:.semibold));Text("\(s.ayahCount) ayat · \(s.revelation=="meccan" ? "Makkiyah":"Madaniyah")").font(.system(size:16)).foregroundStyle(.secondary)};Spacer();Text(s.arabicName).font(.custom("AmiriQuran-Regular",size:23))}.padding(16).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:18))}}}
    }.navigationTitle(state.content.modes.first {$0.id==mode}?.titleId ?? "Al-Qur’an")}
}
struct ThemesView:View {
    @ObservedObject var state:AppState
    var body:some View {PageContainer(dark:state.settings.dark){Text("Pilihan rujukan per tema. Buka ayat untuk membaca konteks dan tafsirnya.");ForEach(state.content.themes){theme in NavigationLink {PageContainer(dark:state.settings.dark){ForEach(theme.references, id:\.self){r in if r.count==2,let v=state.content.corpus.verse(Reference(r[0],r[1])) {Button{state.open(v.reference)}label:{MenuRow(title:state.content.corpus.surahs[v.surah-1].name+" · "+v.reference.id,subtitle:v.indonesian,icon:"book-open-cover",dark:state.settings.dark)}}}}.navigationTitle(theme.title)}label:{MenuRow(title:theme.title,subtitle:"\(theme.references.count) rujukan ayat",icon:"books",dark:state.settings.dark)}};Text("Indeks pilihan Nuraya, bukan tafsir baru atau daftar seluruh ayat tentang tema ini.").font(.footnote).foregroundStyle(.secondary)}.navigationTitle("Terjemah tematik")}
}
struct ReaderView:View {
    @ObservedObject var state:AppState;let target:ReaderDestination;@ObservedObject var audio:AudioService
    @Environment(\.dismiss) var dismiss
    @State private var page=1,reference=Reference(1,1),controls=false,image:UIImage?,error:String?,loading=false,zoom=1.0,hidden=false,landscape=false,tikrar=0
    @State private var panel=false,jump=false,audioSettings=false,actions=false,info=false,downloadingEdition=false,downloadCount=0
    var mode:ReadingMode? {state.content.modes.first {$0.id==target.mode}}
    var edition:MushafEdition? {mode?.edition}
    var body:some View {Group {if let edition=edition {book(edition)}else {textReader}}
        .sheet(isPresented:$panel){NavigationStack{StudyPanel(state:state,reference:reference,audio:audio).toolbar{ToolbarItem(placement:.navigationBarTrailing){Button("Tutup"){panel=false}}}}}
        .sheet(isPresented:$jump){JumpSheet(state:state,edition:edition,onSelect:{r in reference=r;if let edition=edition {do {page=try state.content.index(edition).page(for:r)}catch{self.error="Rujukan tidak ditemukan."}};jump=false},onPage:{n in page=n;updateReference();jump=false})}
        .sheet(isPresented:$audioSettings){AudioRangeSheet(state:state,start:reference,onPlay:{a,b,e,p in audio.verses(qari:state.selectedQari,start:a,end:b,each:e,passes:p);audioSettings=false;controls=true})}
        .confirmationDialog("Ayat \(reference.id)",isPresented:$actions,titleVisibility:.visible){Button("Putar ayat ini"){audio.verses(qari:state.selectedQari,start:reference,end:reference)};Button("Arti, per kata & tafsir"){panel=true};Button("Tandai / hapus penanda"){state.mark(reference)};Button("Salin ayat"){if let v=state.content.corpus.verse(reference){UIPasteboard.general.string=v.text+"\n"+v.indonesian+"\nQS "+reference.id}}}
        .sheet(isPresented:$info){NavigationStack{PageContainer(dark:false){Text("Tajwid & sumber").font(.title.bold());Text("Gambar halaman mengikuti edisi sumber yang dipatok Nuraya. Warna asli cetak tidak selalu memakai legenda panel teks yang sama.");Text("Sumber: agusibrahim/quran-image. Terjemahan panel: Kemenag RI melalui QuranEnc. Arti per kata: Quran.com. Latin: eQuran.id.");if target.mode=="waqaf",let signs=try? state.content.decode("waqaf_guide.json",[WaqafItem].self){ForEach(signs){s in Text(s.mark+" — "+s.name).font(.title2);Text(s.explanation)}};Text("Halaman: \(page)/604. Ketuk halaman untuk menampilkan kontrol; geser kanan untuk lanjut; tekan lama ayat pada edisi berpeta.")}.toolbar{Button("Tutup"){info=false}}}}
        .onAppear{reference=target.reference;if let edition=edition {do{page=try state.content.index(edition).page(for:reference)}catch{self.error="Halaman rujukan tidak ditemukan."}}}
        .onDisappear{audio.stopReader();rotate(false)}
        .onChange(of:audio.track?.id){_ in guard state.settings.followAudio,audio.context == .reader,let r=audio.track?.verse?.reference else{return};reference=r;state.settings.lastRead=r;if let edition=edition,let n=try? state.content.index(edition).page(for:r){page=n}}
    }
    func book(_ edition:MushafEdition)->some View {ZStack{
        Color.mushafPaper.ignoresSafeArea()
        if let image=image {MushafCanvas(image:image,regions:state.content.regions(edition,page),selected:audio.context == .reader ? audio.track?.verse?.reference:nil,zoom:zoom,tap:{withAnimation{controls.toggle()}},doubleTap:{landscape.toggle();rotate(landscape)},select:{r in reference=r;actions=true},turn:{turn($0)}).saturation(state.settings.tajwid ? 1:0).ignoresSafeArea(edges:.bottom)}
        if hidden {Color.mushafPaper;Button("Tampilkan kembali halaman"){hidden=false}.font(.title3).padding()}
        if loading {ProgressView("Memuat halaman…").padding(20).background(Color.mushafPaper,in:RoundedRectangle(cornerRadius:18))}
        if let error=error {VStack(spacing:18){Text(error);Button("Coba lagi"){Task{await loadPage(edition)}};Button("Kembali"){dismiss()}}.padding(24).background(Color.mushafPaper,in:RoundedRectangle(cornerRadius:18))}
        if controls {VStack{HStack(spacing:10){Button{dismiss()}label:{AppIcon(name:"arrow-left").frame(width:44,height:44)};VStack(alignment:.leading){Text(mode?.titleId ?? edition.title).font(.system(size:15,weight:.semibold));Text("Halaman \(page) / 604").font(.system(size:13))};Spacer();Button{panel=true}label:{AppIcon(name:"language").frame(width:40,height:44)};Button{jump=true}label:{AppIcon(name:"search").frame(width:40,height:44)};readerMenu}.padding(.horizontal,8).background(Color(hex:0xF4ECD7));Spacer();if downloadingEdition {Text("Mengunduh edisi: \(downloadCount)/604").padding(12).background(Color(hex:0xF4ECD7));Button("Hentikan unduhan"){downloadingEdition=false}.padding(8).background(Color(hex:0xF4ECD7))};HStack(spacing:12){Button{info=true}label:{AppIcon(name:"info").frame(width:44,height:48)};Button{state.mark(reference)}label:{AppIcon(name:"bookmark").frame(width:44,height:48)};Button{audioSettings=true}label:{HStack{AppIcon(name:"settings-sliders");Text(state.selectedQari.name).font(.system(size:13)).lineLimit(2);Spacer();AppIcon(name:"angle-down",size:18)}};if audio.context == .reader,audio.track != nil {Button{audio.toggle()}label:{AppIcon(name:audio.playing ? "pause":"play").frame(width:44,height:48)}}}.padding(.horizontal,10).background(Color(hex:0xF4ECD7))}.foregroundStyle(Color(hex:0x625331))}
    }.statusBarHidden(!controls).task(id:page){await loadPage(edition)}}
    var readerMenu:some View {Menu{Button("Halaman berikutnya"){turn(1)};Button("Halaman sebelumnya"){turn(-1)};Button("Lanskap / potret"){landscape.toggle();rotate(landscape)};Button("Perbesar halaman"){zoom=min(3,zoom+0.5)};Button("Ukuran halaman semula"){zoom=1};Button("Layar baca penuh"){controls=false};Button("Simpan halaman offline"){if let edition=edition {Task{await loadPage(edition)}}};Button("Unduh 604 halaman edisi ini"){downloadEdition()};if target.mode=="hafalan_8"{Button("Uji hafalan tanpa melihat"){hidden.toggle()}};if target.mode=="tikrar" {Button("Catat pengulangan: \(tikrar)"){tikrar+=1};Button("Atur pengulangan audio"){audioSettings=true}};Button("Info tajwid & sumber"){info=true}}label:{AppIcon(name:"menu-dots-vertical").frame(width:40,height:44)}}
    var textReader:some View {NavigationStack{ScrollViewReader{proxy in ScrollView{LazyVStack(spacing:20){ForEach(state.content.corpus.chapter(reference.surah)){v in VStack(alignment:.leading,spacing:16){HStack{Text("\(state.content.corpus.surahs[v.surah-1].name) · \(v.ayah)").font(.headline);Spacer();Button{reference=v.reference;actions=true}label:{AppIcon(name:"menu-dots-vertical").frame(width:44,height:44)}};if let opening=v.opening {ArabicText(text:opening,size:state.settings.arabicSize).padding(.vertical,12)};ArabicText(text:v.text,size:state.settings.arabicSize,study:state.content.study(v.reference),color:state.settings.tajwid,highlight:audio.track?.verse?.reference==v.reference ? audio.word:nil);if state.settings.translation != "none" {Text(state.settings.translation=="en" ? v.english:v.indonesian).font(.system(size:19)).textSelection(.enabled)};HStack{Button("Arti & tafsir"){reference=v.reference;panel=true};Spacer();Button{audio.verses(qari:state.selectedQari,start:v.reference,end:v.reference)}label:{AppIcon(name:"play").frame(width:48,height:48)}}}.padding(20).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:22)).id(v.ayah)};HStack{if reference.surah>1 {Button("Surah sebelumnya"){reference=Reference(reference.surah-1,1);state.settings.lastRead=reference}};Spacer();if reference.surah<114{Button("Surah berikutnya"){reference=Reference(reference.surah+1,1);state.settings.lastRead=reference}}}}.padding(20)}.background(Palette(dark:state.settings.dark).background).onChange(of:reference){r in withAnimation{proxy.scrollTo(r.ayah,anchor:.top)}}.onAppear{DispatchQueue.main.asyncAfter(deadline:.now()+0.3){proxy.scrollTo(target.reference.ayah,anchor:.top)}}}.navigationTitle(state.content.corpus.surahs[reference.surah-1].name).navigationBarTitleDisplayMode(.inline).toolbar{ToolbarItem(placement:.navigationBarLeading){Button{dismiss()}label:{AppIcon(name:"arrow-left")}};ToolbarItemGroup(placement:.navigationBarTrailing){Button{jump=true}label:{AppIcon(name:"search")};Button{audioSettings=true}label:{AppIcon(name:"settings-sliders")}}}}
    func turn(_ delta:Int){guard (1...604).contains(page+delta) else{return};page+=delta;zoom=1;updateReference()}
    func updateReference(){if let edition=edition,let index=try? state.content.index(edition),let r=index.references(on:page).first {reference=r;state.settings.lastRead=r}}
    func loadPage(_ edition:MushafEdition) async {loading=true;error=nil;let n=page;do{let i=try await state.downloads.page(edition,n);if page==n{image=i}}catch{if page==n{self.error="Halaman belum terbuka: \(error.localizedDescription)"}};if page==n{loading=false}}
    func downloadEdition(){guard let edition=edition else{return};downloadingEdition=true;Task{for n in 1...604{guard downloadingEdition else{return};do{_=try await state.downloads.page(edition,n);downloadCount=n}catch{self.error="Unduhan berhenti pada halaman \(n). Halaman yang selesai tetap tersimpan.";downloadingEdition=false;return}};downloadingEdition=false}}
    func rotate(_ landscape:Bool){guard let scene=UIApplication.shared.connectedScenes.first as? UIWindowScene else{return};scene.requestGeometryUpdate(.iOS(interfaceOrientations:landscape ? .landscapeRight:.portrait))}
}
struct StudyPanel:View {
    @ObservedObject var state:AppState;let reference:Reference;@ObservedObject var audio:AudioService
    @State private var tab=0
    var body:some View {PageContainer(dark:state.settings.dark){if let v=state.content.corpus.verse(reference){Text(state.content.corpus.surahs[v.surah-1].name+" · "+reference.id).font(.title2.bold());ArabicText(text:v.text,size:state.settings.arabicSize,study:state.content.study(reference),color:state.settings.tajwid,highlight:audio.track?.verse?.reference==reference ? audio.word:nil);Picker("Bantuan baca",selection:$tab){Text("Arti").tag(0);Text("Per kata").tag(1);Text("Tafsir").tag(2);Text("Latin").tag(3)}.pickerStyle(.segmented)
        if tab==0 {Text(v.indonesian).font(.system(size:19)).textSelection(.enabled);if let notes=v.indonesianFootnotes{Text(notes).font(.footnote)};Text("Kementerian Agama RI · QuranEnc").font(.footnote).foregroundStyle(.secondary)}
        if tab==1,let study=state.content.study(reference){ForEach(study.words){w in HStack{Text(w.indonesian ?? w.english ?? "Arti belum tersedia");Spacer();Text(w.arabic).font(.custom("AmiriQuran-Regular",size:29))}.padding(14).background(Palette(dark:state.settings.dark).card,in:RoundedRectangle(cornerRadius:14))};Text("Arti kata: Quran.com").font(.footnote)}
        if tab==2 {Text(state.content.study(reference)?.tafsir ?? "Tafsir belum tersedia untuk rujukan ini.").font(.system(size:18)).textSelection(.enabled);Text(state.content.study(reference)?.tafsirSource ?? "Kemenag RI · eQuran.id").font(.footnote)}
        if tab==3 {Text(state.content.latin(reference) ?? "Latin belum tersedia.").font(.system(size:20));Text("Transliterasi eQuran.id. Latin membantu belajar; pelafalan tetap dipelajari melalui bacaan Arab dan guru.").font(.footnote)}
    }}.navigationTitle("Arti & bantuan baca")}
}
struct JumpSheet:View {
    @ObservedObject var state:AppState;let edition:MushafEdition?;let onSelect:(Reference)->Void,onPage:(Int)->Void
    @State private var choice=0,number="",query=""
    var body:some View {NavigationStack{PageContainer(dark:state.settings.dark){Picker("Tujuan",selection:$choice){if edition != nil{Text("Halaman").tag(0)};Text("Surah").tag(1);Text("Juz").tag(2)}.pickerStyle(.segmented);if choice==0,edition != nil {TextField("Nomor 1–604",text:$number).keyboardType(.numberPad).textFieldStyle(.roundedBorder);PrimaryButton(title:"Buka halaman"){if let n=Int(number),(1...604).contains(n){onPage(n)}}.disabled(!(Int(number).map {(1...604).contains($0)} ?? false))}else if choice==2 {ForEach(1...30,id:\.self){j in Button("Juz \(j)"){if let v=state.content.corpus.verses.first(where:{$0.juz==j}){onSelect(v.reference)}}.frame(minHeight:48)}}else {TextField("Cari surah",text:$query).textFieldStyle(.roundedBorder);ForEach(state.content.corpus.surahs.filter{query.isEmpty || Normalization.search($0.name).contains(Normalization.search(query)) || String($0.id)==query}){s in Button{onSelect(Reference(s.id,1))}label:{MenuRow(title:"\(s.id). \(s.name)",icon:"book-open-cover",dark:state.settings.dark)}}}}.navigationTitle("Buka bacaan").onAppear{if edition==nil{choice=1}}}}
}
struct AudioRangeSheet:View {
    @ObservedObject var state:AppState;let start:Reference,onPlay:(Reference,Reference,Int,Int)->Void
    @State private var startSurah=1,startAyah=1,endSurah=1,endAyah=1,each=1,passes=1
    var valid:Bool {startSurah<endSurah || (startSurah==endSurah && startAyah<=endAyah)}
    var body:some View {NavigationStack{Form{Section("Qari"){Picker("Suara",selection:$state.settings.qari){ForEach(state.content.qaris){q in Text(q.name).tag(q.id)}}};Section("Awal"){surahPicker("Surah",selection:$startSurah);Stepper("Ayat \(startAyah)",value:$startAyah,in:1...state.content.corpus.surahs[startSurah-1].ayahCount)};Section("Akhir"){surahPicker("Surah",selection:$endSurah);Stepper("Ayat \(endAyah)",value:$endAyah,in:1...state.content.corpus.surahs[endSurah-1].ayahCount)};Section("Pengulangan"){Stepper("Ulang setiap ayat: \(each)×",value:$each,in:1...20);Stepper("Putaran rentang: \(passes)×",value:$passes,in:1...20);Text("Pengulangan per ayat dan seluruh rentang berbeda. Maksimal 20 pengulangan gabungan.")};Button("Mulai mendengarkan"){onPlay(Reference(startSurah,startAyah),Reference(endSurah,endAyah),each,passes)}.disabled(!valid || each*passes>20)}.navigationTitle("Audio bacaan").onAppear{startSurah=start.surah;endSurah=start.surah;startAyah=start.ayah;endAyah=state.content.corpus.surahs[start.surah-1].ayahCount}.onChange(of:startSurah){_ in startAyah=1}.onChange(of:endSurah){_ in endAyah=1}}}
    func surahPicker(_ label:String,selection:Binding<Int>)->some View {Picker(label,selection:selection){ForEach(state.content.corpus.surahs){Text("\($0.id). \($0.name)").tag($0.id)}}}
}
